package com.primehr.rsp.evaluation.api;
import com.primehr.rsp.evaluation.domain.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.*; import java.time.*; import java.util.*;
public final class EvaluationPolicyDtos {private EvaluationPolicyDtos(){}
 public record CriterionInput(@NotBlank @Size(max=80)String code,@NotBlank @Size(max=300)String label,@Size(max=2000)String instructions,@NotNull @DecimalMin("0") @DecimalMax("100")BigDecimal weight,@DecimalMin(value="0",inclusive=false)BigDecimal maximumScore,boolean requiresRemarks,@PositiveOrZero int displayOrder){}
 public record StageInput(@NotBlank @Size(max=80)String code,@NotBlank @Size(max=200)String name,@Size(max=2000)String instructions,@NotNull EvaluationStage.Type type,@NotNull EvaluationStage.Mode mode,@NotNull @DecimalMin("0") @DecimalMax("100")BigDecimal weight,@DecimalMin(value="0",inclusive=false)BigDecimal maximumScore,@DecimalMin("0")BigDecimal passingScore,@Min(1)int minimumRaters,boolean requiresEvidence,@PositiveOrZero int displayOrder,@NotEmpty List<@Valid CriterionInput> criteria){}
 public record SavePolicy(@NotBlank @Size(max=80)String code,@NotBlank @Size(max=200)String name,@Size(max=2000)String description,@NotBlank @Size(max=500)String meritSelectionPlanReference,@Min(0)@Max(6)int roundingScale,@NotNull EvaluationPolicy.Rounding roundingMode,@NotNull EvaluationPolicy.TieRule tieRule,@NotEmpty List<@Valid StageInput> stages,Long recordVersion){}
 public record Publish(@NotNull Long recordVersion,@NotNull LocalDate effectiveFrom,LocalDate effectiveTo){} public record Transition(@NotNull Long recordVersion){}
 public record CriterionResponse(String id,String code,String label,String instructions,BigDecimal weight,BigDecimal maximumScore,boolean requiresRemarks,int displayOrder){}
 public record StageResponse(String id,String code,String name,String instructions,String type,String mode,BigDecimal weight,BigDecimal maximumScore,BigDecimal passingScore,int minimumRaters,boolean requiresEvidence,int displayOrder,List<CriterionResponse> criteria){}
 public record PolicyResponse(String id,String code,String name,String description,String meritSelectionPlanReference,int definitionVersion,String supersedesId,String status,LocalDate effectiveFrom,LocalDate effectiveTo,int roundingScale,String roundingMode,String tieRule,String aggregationMode,String publishedBy,Instant publishedAt,long recordVersion,List<StageResponse> stages){}
 public record BindPolicy(@NotBlank String policyId,@NotNull Long policyRecordVersion,@NotNull Long publicationRecordVersion){}
 public record BindingResponse(String id,String publicationId,String policyId,String policyCode,int policyDefinitionVersion,String policyFingerprint,String boundBy,Instant boundAt,long recordVersion){}
}
